module Control_unit (output reg Clr_P1_P0, Ld_P1_P0, Ld_R0, input En, Ld, clock, rst);  parameter S_idle = 4'b0001, S_1 = 4'b0010, S_full = 4'b0100, S_wait = 4'b1000;  reg [3: 0] state, next_state;  always @ (posedge clock)    if (rst) state <= S_idle;    else state <= next_state;  always @ (state, Ld, En) begin    Clr_P1_P0 = 0;				// Assign by exception    Ld_P1_P0 = 0;    Ld_R0 = 0;    next_state = S_idle;    case (state)      S_idle:		if (En) begin Ld_P1_P0 = 1; next_state = S_1; end				else next_state = S_idle;      S_1:		begin Ld_P1_P0 = 1; next_state = S_full; end      S_full:		if (!Ld) next_state = S_wait; 				else begin 		  		  Ld_R0 = 1;		 		  if (En) begin Ld_P1_P0 = 1; next_state = S_1;  end		  		  else begin Clr_P1_P0 = 1; next_state = S_idle; end				end      S_wait:	if (!Ld) next_state = S_wait;				else begin		  		  Ld_R0 = 1;		 		  if (En) begin Ld_P1_P0 = 1; next_state = S_1; end		  		  else begin Clr_P1_P0 = 1; next_state = S_idle;  end				end      default:	next_state = S_idle;    endcase  endendmodule// Test bench for control unitmodule t_Control_unit ();  wire 	Clr_P1_P0, Ld_P1_P0, Ld_R0;   reg	En, Ld, clock, rst;  Control_unit M0 (Clr_P1_P0, Ld_P1_P0, Ld_R0, En, Ld, clock, rst);  initial #200 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin rst = 0; #2 rst = 1; #12 rst = 0; end  initial fork    #20 Ld = 0;    #20 En = 0;	    #30 En = 1;	// Drive to S_wait    #70 Ld = 1;	// Return to S_1 to S_full tp S_wait    #80 Ld = 0;     #100 Ld = 1;	// Drive to S_idle    #100 En = 0;    #110 En = 0;    #120 Ld = 0;  joinendmodulemodule Control_unit (output reg Clr_P1_P0, Ld_P1_P0, Ld_R0, input En, Ld, clock, rst);  parameter S_idle = 4'b0001, S_1 = 4'b0010, S_full = 4'b0100, S_wait = 4'b1000;  reg [3: 0] state, next_state;  always @ (posedge clock)    if (rst) state <= S_idle;    else state <= next_state;  always @ (state, Ld, En) begin    Clr_P1_P0 = 0;				// Assign by exception    Ld_P1_P0 = 0;    Ld_R0 = 0;    next_state = S_idle;    case (state)      S_idle:		if (En) begin Ld_P1_P0 = 1; next_state = S_1; end				else next_state = S_idle;      S_1:		begin Ld_P1_P0 = 1; next_state = S_full; end      S_full:		if (!Ld) next_state = S_wait; 				else begin 		  		  Ld_R0 = 1;		 		  if (En) begin Ld_P1_P0 = 1; next_state = S_1;  end		  		  else begin Clr_P1_P0 = 1; next_state = S_idle; end				end      S_wait:	if (!Ld) next_state = S_wait;				else begin		  		  Ld_R0 = 1;		 		  if (En) begin Ld_P1_P0 = 1; next_state = S_1; end		  		  else begin Clr_P1_P0 = 1; next_state = S_idle;  end				end      default:	next_state = S_idle;    endcase  endendmodule		